package pe.edu.utec.labreserve.service;
import org.springframework.data.domain.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import pe.edu.utec.labreserve.config.UserPrincipal; import pe.edu.utec.labreserve.dto.request.CreateOrderRequestDto; import pe.edu.utec.labreserve.dto.response.*; import pe.edu.utec.labreserve.entity.*; import pe.edu.utec.labreserve.exception.*; import pe.edu.utec.labreserve.repository.*; import java.math.BigDecimal; import java.time.ZonedDateTime;
@Service public class OrderService{private final ProductRepository products; private final StoreRepository stores; private final FoodOrderRepository orders; private final UserRepository users; private final pe.edu.utec.labreserve.event.OrderConfirmedEventPublisher publisher;
 public OrderService(ProductRepository products,StoreRepository stores,FoodOrderRepository orders,UserRepository users,pe.edu.utec.labreserve.event.OrderConfirmedEventPublisher publisher){this.products=products;this.stores=stores;this.orders=orders;this.users=users;this.publisher=publisher;}
 @Transactional public OrderResponseDto create(CreateOrderRequestDto r,UserPrincipal user){Product p=products.findByIdForUpdate(r.productId()).orElseThrow(()->new ProductNotFoundException("productId: "+r.productId())); Store s=stores.findById(p.getStoreId()).orElseThrow(()->new StoreNotFoundException("storeId: "+p.getStoreId())); if(!"AVAILABLE".equals(p.getStatus())||!"OPEN".equals(s.getStatus()))throw new ProductNotAvailableException(); if(s.getOwnerId().equals(user.getId()))throw new ProductNotAvailableException("El dueño no puede comprar su propio producto"); if(r.quantity()>p.getStock())throw new InsufficientStockException(); BigDecimal total=p.getPrice().multiply(BigDecimal.valueOf(r.quantity())); p.setStock(p.getStock()-r.quantity()); if(p.getStock()==0)p.setStatus("SOLD_OUT"); products.save(p); FoodOrder o=orders.save(new FoodOrder(user.getId(),p.getId(),r.quantity(),total,ZonedDateTime.now(),"CONFIRMED")); publisher.publish(o.getId(),user.getId(),total); return new OrderResponseDto(o.getId(),o.getProductId(),user.getUsername(),o.getQuantity(),o.getTotalAmount(),o.getStatus());}
 @Transactional(readOnly=true) public PagedResponseDto<MyOrderResponseDto> myOrders(UserPrincipal user,int page,int size){Page<FoodOrder> p=orders.findByCustomerId(user.getId(),PageRequest.of(page,size,Sort.by("createdAt").descending())); return new PagedResponseDto<>(p.getContent().stream().map(o->new MyOrderResponseDto(o.getId(),products.findById(o.getProductId()).map(Product::getName).orElse(""),o.getStatus())).toList(),p.getNumber(),p.getSize(),p.getTotalElements());}
}
